using _Game;
using DG.Tweening;
using UnityEngine;

/// <summary>
/// Orchestrator của Tutorial Lv2 Start Sequence.
/// Fire actions theo thứ tự → các subscriber (WorldMap, NPC…) tự xử lý visual.
/// WorldMap.Start() gọi Begin() nếu IsActive().
/// </summary>
public class TutorialLv2Start : MonoBehaviour
{
    // ----------------------------------------------------------
    //  State check
    // ----------------------------------------------------------

    public bool IsActive() =>
        DataSave.TutorialData.isLv1EndSequenceComplete &&
        !DataSave.TutorialData.isLv2StartTutComplete;

    // ----------------------------------------------------------
    //  Entry point — WorldMap gọi khi vào Lobby lần đầu
    // ----------------------------------------------------------

    public void Begin()
    {
        if (!IsActive()) return;

        ShowLobbyFog();
        DOVirtual.DelayedCall(4.5f, () => ShowNPC());
    }

    // ----------------------------------------------------------
    //  Phase 1 — Bật anim fog (anim tự xử lý tàu đến + mây bay ra)
    // ----------------------------------------------------------

    public void ShowLobbyFog()
    {
        TutorialLv2StartActions.ShowLobbyFog?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 3 — NPC xuất hiện nói chuyện
    // ----------------------------------------------------------

    public void ShowNPC()
    {
        TutorialLv2StartActions.ShowNPC?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 4 — NPC biến mất → chuyển sang phase tiếp theo
    // ----------------------------------------------------------

    public void HideNPC()
    {
        TutorialLv2StartActions.HideNPC?.Invoke();
        AnimateLevelIcon();
    }

    // ----------------------------------------------------------
    //  Phase 5 — Icon player nhảy lên level 2
    // ----------------------------------------------------------

    public void AnimateLevelIcon()
    {
        TutorialLv2StartActions.AnimateLevelIcon?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 6 — Button level xuất hiện + bàn tay chỉ
    // ----------------------------------------------------------

    public void ShowLevelButton()
    {
        TutorialLv2StartActions.ShowLevelButton?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 7 — Popup xuất hiện + bàn tay chỉ nút play
    // ----------------------------------------------------------

    public void ShowLevelPopup()
    {
        TutorialLv2StartActions.ShowLevelPopup?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 8 — Hoàn thành tutorial (player play hoặc tắt popup)
    // ----------------------------------------------------------

    public void CompleteTutorial()
    {
        if (!IsActive()) return;

        DataSave.TutorialData.SetLv2StartTutComplete();
        TutorialLv2StartActions.CompleteTutorial?.Invoke();
    }
}

using System;

/// <summary>
/// Actions của Tutorial Lv2 Start Sequence (lần đầu vào Lobby sau khi hoàn thành Lv1).
/// Lobby fires → TutorialLv2Start reacts.
/// </summary>
public static class TutorialLv2StartActions
{
    /// <summary>Lần đầu vào Lobby → che lobby bằng mây khói tạo bí ẩn</summary>
    public static Action ShowLobbyFog;

    /// <summary>Mây bay ra hết → NPC xuất hiện nói chuyện rủ rê player khám phá</summary>
    public static Action ShowNPC;

    /// <summary>NPC kết thúc thoại → NPC biến mất</summary>
    public static Action HideNPC;

    /// <summary>NPC biến mất → icon player nhảy từ level 1 lên level 2</summary>
    public static Action AnimateLevelIcon;

    /// <summary>Icon dừng → button chơi level xuất hiện, bàn tay chỉ vào button</summary>
    public static Action ShowLevelButton;

    /// <summary>Player ấn button → popup xuất hiện, bàn tay chỉ vào nút play</summary>
    public static Action ShowLevelPopup;

    /// <summary>Player ấn play hoặc chủ động tắt popup → hoàn thành tutorial</summary>
    public static Action CompleteTutorial;
}

using System;

namespace _Game
{
    [Serializable]
    public class TutorialData
    {
        #region Lv1 

        // Note: Đã hoàn thành tutorial level 1 chưa
        public bool isLevel1Completed;

        public void SetLv1Completed()
        {
            SetTutorialComplete(ref isLevel1Completed);
        }

        #endregion

        #region Lv1 End Sequence

        public bool isLv1EndSequenceComplete;

        public void SetLv1EndSequenceComplete()
        {
            SetTutorialComplete(ref isLv1EndSequenceComplete);
        }

        #endregion

        #region Lv2 Start Tutorial

        public bool isLv2StartTutComplete;

        public void SetLv2StartTutComplete()
        {
            SetTutorialComplete(ref isLv2StartTutComplete);
        }

        #endregion

        #region Booster lv 2,4,6

        public bool isTutBoosterHintComplete;
        public bool hasClaimHint;

        public bool isTutBoosterMagnifierComplete;
        public bool hasClaimMagnifier;

        public bool isTutBoosterFreezeTimeComplete;
        public bool hasClaimFreezeTime;

        #endregion

        #region Set Methods

        public void SetTutBoosterHintComplete()
        {
            isTutBoosterHintComplete = true;
            DataSave.SaveTutorialData();
        }

        public void SetTutBoosterMagnifierComplete()
        {
            isTutBoosterMagnifierComplete = true;
            DataSave.SaveTutorialData();
        }

        public void SetTutBoosterFreezeTimeComplete()
        {
            isTutBoosterFreezeTimeComplete = true;
            DataSave.SaveTutorialData();
        }

        public void SetHasClaimHint(bool value)
        {
            hasClaimHint = value;
            DataSave.SaveTutorialData();
        }

        public void SetHasClaimMagnifier(bool value)
        {
            hasClaimMagnifier = value;
            DataSave.SaveTutorialData();
        }

        public void SetHasClaimFreezeTime(bool value)
        {
            hasClaimFreezeTime = value;
            DataSave.SaveTutorialData();
        }


        // Note: Set has claim theo loại booster
        public void SetHasClaim(InGameBoosterBase.EType boosterType, bool value)
        {
            switch (boosterType)
            {
                case InGameBoosterBase.EType.Hint:
                    DataSave.TutorialData.SetHasClaimHint(value);
                    break;
                case InGameBoosterBase.EType.Magnifier:
                    DataSave.TutorialData.SetHasClaimMagnifier(value);
                    break;
                case InGameBoosterBase.EType.FreezeTime:
                    DataSave.TutorialData.SetHasClaimFreezeTime(value);
                    break;
            }
        }

        #endregion

        #region Utility Methods

        // Note: Method chung để set tutorial complete và save
        private void SetTutorialComplete(ref bool tutorialFlag)
        {
            tutorialFlag = true;
            DataSave.SaveTutorialData();
        }

        #endregion
    }
}

