using System.Collections.Generic;
using UnityEngine;

namespace _Game
{
    /// <summary>
    /// Quản lý tài nguyên của người chơi với validation và tracking
    /// </summary>
    public class ResourceData
    {
        // Note: Resources
        public int gold;
        public int heart = 5;
        public int maxHearts = 5;

        // Note: In-game Boosters
        public int hintBooster;
        public int magnifierBooster;
        public int freezeTimeBooster;
        public int compassBooster;

        // Note: Pre-play Boosters
        public int magicWandBooster;
        public int premiumClockBooster;
        public int boxUpgradeBooster;

        // Note: Stars (World Map)
        public int stars;

        // Note: First time
        public bool isFirstTimeOpen = true;
        // Note: Ad Inter
        public bool canShowAdInter;

        #region Generic Resource Methods

        private bool ChangeResource(ref int resource, int delta, EventID eventId, bool allowNegative = false)
        {
            if (GameManager.Instance.IsMode(GameManager.EMode.CheatUAC) && delta < 0)
            {
                GameManager.Instance.PostEvent(eventId);
                return true;
            }

            int newValue = resource + delta;

            if (!allowNegative && newValue < 0)
            {
                Debug.LogWarning($"[ResourceData] Không đủ resource! Current: {resource}, Delta: {delta}");
                return false;
            }

            resource = newValue;
            GameManager.Instance.PostEvent(eventId);
            DataSave.SavePlayerResourceData();
            return true;
        }

        private void SetResource(ref int resource, int value, EventID eventId, bool allowNegative = false)
        {
            if (!allowNegative && value < 0)
            {
                Debug.LogWarning($"[ResourceData] Giá trị không hợp lệ: {value}");
                value = 0;
            }

            if (GameManager.Instance.IsMode(GameManager.EMode.Normal))
                resource = value;
            GameManager.Instance.PostEvent(eventId);
            DataSave.SavePlayerResourceData();
        }

        #endregion

        #region Change Resource By Type

        public void ChangeResourceValue(List<RewardData> listRewardData, string claimType = ClaimType.Free,
            string placement = PlacementName.Unknown)
        {
            foreach (var rewardData in listRewardData)
            {
                this.ChangeResourceValue(rewardData, claimType, placement);
            }
        }

        public void ChangeResourceValue(RewardData rewardData, string claimType = ClaimType.Free,
            string placement = PlacementName.Unknown)
        {
            this.ChangeResourceValue(rewardData.type, rewardData.value, claimType, placement);
        }

        /// <summary>
        /// Change resource value với tracking tự động dựa vào ResourcesType
        /// Hỗ trợ cả tăng và giảm
        /// </summary>
        public void ChangeResourceValue(ResourcesType resourceType, int value, string claimType = ClaimType.Free,
            string placement = PlacementName.Unknown)
        {
            switch (resourceType)
            {
                case ResourcesType.none:
                    Debug.LogWarning("[ResourceData] Type is none, skipping...");
                    return;

                // Note: Resources
                case ResourcesType.stars:
                    ChangeResource(ref stars, value, EventID.UpdateStars);
                    return;

                case ResourcesType.gold:
                    // Note: VIP bonus chỉ áp dụng khi tăng
                    if (value > 0 && DataSave.ShopData.HasPurchasedVip)
                    {
                        value *= 2;
                    }

                    ChangeGoldValue(value, claimType, placement);
                    return;

                case ResourcesType.heart:
                    ChangeHeartValue(value);
                    return;

                case ResourcesType.infiniteHeart:
                    DataSave.InfiniteHeartData.Activate(value);
                    Debug.Log($"[ResourceData] Infinite Heart: {value}s");
                    return;

                // Note: Boosters
                case ResourcesType.boosterHint:
                case ResourcesType.boosterMagnifier:
                case ResourcesType.boosterFreezeTime:
                case ResourcesType.boosterCompass:
                case ResourcesType.boosterMagicWand:
                case ResourcesType.boosterPremiumClock:
                case ResourcesType.boosterBoxUpgrade:
                    ChangeBoosterValue(resourceType, value, claimType, placement);
                    return;

                default:
                    Debug.LogWarning($"[ResourceData] Unknown resource type: {resourceType}");
                    return;
            }
        }

        #endregion

        #region Booster Universal Method

        /// <summary>
        /// Change booster value với tracking tự động dựa vào ResourcesType
        /// </summary>
        private bool ChangeBoosterValue(ResourcesType boosterType, int value, string claimType = ClaimType.Free,
            string placement = PlacementName.Unknown)
        {
            // Note: Dùng ToString() để lấy tên powerup
            string powerupName = boosterType.ToString().ToLower();

            // Note: Track event
            if (value > 0)
            {
                AnalyticsTracking.Instance.OnPowerupClaim(powerupName, claimType, placement, value);
            }
            else if (value < 0)
            {
                AnalyticsTracking.Instance.OnPowerupUse(powerupName, placement, Mathf.Abs(value));
            }

            // Note: Gọi method tương ứng
            switch (boosterType)
            {
                case ResourcesType.boosterHint:
                    return ChangeResource(ref hintBooster, value, EventID.UpdateHintBooster);

                case ResourcesType.boosterMagnifier:
                    return ChangeResource(ref magnifierBooster, value, EventID.UpdateMagnifierBooster);

                case ResourcesType.boosterFreezeTime:
                    return ChangeResource(ref freezeTimeBooster, value, EventID.UpdateFreezeTimeBooster);

                case ResourcesType.boosterCompass:
                    return ChangeResource(ref compassBooster, value, EventID.UpdateCompassBooster);

                case ResourcesType.boosterMagicWand:
                    return ChangeResource(ref magicWandBooster, value, EventID.UpdateMagicWandBooster);

                case ResourcesType.boosterPremiumClock:
                    return ChangeResource(ref premiumClockBooster, value, EventID.UpdatePremiumClockBooster);

                case ResourcesType.boosterBoxUpgrade:
                    return ChangeResource(ref boxUpgradeBooster, value, EventID.UpdateBoxUpgradeBooster);

                default:
                    Debug.LogWarning($"[ResourceData] Unknown booster type: {boosterType}");
                    return false;
            }
        }

        #endregion

        #region Gold

        private bool ChangeGoldValue(int value, string claimType = ClaimType.Free,
            string placement = PlacementName.Unknown)
        {
            if (value > 0)
            {
                AnalyticsTracking.Instance.OnCoinsClaim(claimType, placement, value);
            }
            else if (value < 0)
            {
                AnalyticsTracking.Instance.OnCoinsSpend(placement, Mathf.Abs(value));
            }

            return ChangeResource(ref gold, value, EventID.UpdateGold);
        }

        public void SetGoldValue(int value) => SetResource(ref gold, value, EventID.UpdateGold);

        #endregion

        #region Heart

        private bool ChangeHeartValue(int value)
        {
            bool result = ChangeResource(ref heart, value, EventID.UpdateHeart);

            if (result && value < 0)
            {
                DataSave.HeartCooldownData.StartCooldown();
            }

            return result;
        }

        public void SetHeartValue(int value) => SetResource(ref heart, value, EventID.UpdateHeart);

        #endregion

        public bool IsMagicWandBoosterUnlocked()
        {
            return GameConfig.Instance.boosterConfig.IsMagicWandBoosterUnlocked();
        }

        public bool IsPremiumClockBoosterUnlocked()
        {
            return GameConfig.Instance.boosterConfig.IsPremiumClockBoosterUnlocked();
        }

        public bool IsBoxUpgradeBoosterUnlocked()
        {
            return GameConfig.Instance.boosterConfig.IsBoxUpgradeBoosterUnlocked();
        }


        #region Booster Set Methods

        public void SetHintBoosterValue(int value) =>
            SetResource(ref hintBooster, value, EventID.UpdateHintBooster);

        public void SetMagnifierBoosterValue(int value) =>
            SetResource(ref magnifierBooster, value, EventID.UpdateMagnifierBooster);

        public void SetFreezeTimeBoosterValue(int value) =>
            SetResource(ref freezeTimeBooster, value, EventID.UpdateFreezeTimeBooster);

        public void SetCompassBoosterValue(int value) =>
            SetResource(ref compassBooster, value, EventID.UpdateCompassBooster);

        public void SetMagicWandBoosterValue(int value) =>
            SetResource(ref magicWandBooster, value, EventID.UpdateMagicWandBooster);

        public void SetPremiumClockBoosterValue(int value) =>
            SetResource(ref premiumClockBooster, value, EventID.UpdatePremiumClockBooster);

        public void SetBoxUpgradeBoosterValue(int value) =>
            SetResource(ref boxUpgradeBooster, value, EventID.UpdateBoxUpgradeBooster);

        #endregion

        #region First Time Open

        public void ChangeFirstTimeStatus(bool value)
        {
            isFirstTimeOpen = value;
            DataSave.SavePlayerResourceData();
        }

        #endregion

        #region Helper Methods

        public bool IsHeartFull()
        {
            return heart >= maxHearts;
        }

        public void EarnStar(int amount = 1)
        {
            ChangeResourceValue(ResourcesType.stars, amount);
        }

        #endregion
    }
}

