using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// UI phủ toàn màn hình cho NPC trong Tutorial Lv2.
/// Hiện khi ShowNPC fired, ẩn khi player ấn button hoặc HideNPC fired.
/// </summary>
public class TutorialLv2NPCDialog : MonoBehaviour
{
    [SerializeField] private GameObject panel;
    [SerializeField] private Button confirmButton;

    private void Awake()
    {
        confirmButton.onClick.AddListener(OnClickConfirm);
    }

    private void OnEnable()
    {
        TutorialLv2StartActions.ShowNPC += ShowNPC;
        TutorialLv2StartActions.HideNPC += HideNPC;
    }

    private void OnDisable()
    {
        TutorialLv2StartActions.ShowNPC -= ShowNPC;
        TutorialLv2StartActions.HideNPC -= HideNPC;
    }

    // ----------------------------------------------------------
    //  Handlers
    // ----------------------------------------------------------

    private void ShowNPC()
    {
        panel.SetActive(true);
    }

    private void HideNPC()
    {
        panel.SetActive(false);
    }

    // ----------------------------------------------------------
    //  Button
    // ----------------------------------------------------------

    private void OnClickConfirm()
    {
        TutorialCtrl.Instance.Lv2Start.HideNPC();
    }
}

