using UnityEngine;

/// <summary>
/// Tấm UI transparent full-screen chặn click trong Tutorial Lv2.
/// Bật khi ShowLobbyFog, tắt khi ShowLevelButton (player được phép bấm vào level node).
/// Đặt Canvas Sort Order cao hơn toàn bộ Lobby UI.
/// </summary>
public class TutorialLv2Blocker : MonoBehaviour
{
    [SerializeField] private GameObject blockerPanel;

    private void OnEnable()
    {
        TutorialLv2StartActions.ShowLobbyFog   += Show;
        TutorialLv2StartActions.ShowLevelButton += Hide;
    }

    private void OnDisable()
    {
        TutorialLv2StartActions.ShowLobbyFog   -= Show;
        TutorialLv2StartActions.ShowLevelButton -= Hide;
    }

    private void Show() => blockerPanel.SetActive(true);
    private void Hide() => blockerPanel.SetActive(false);
}

