using UnityEngine;

public class WorldMapTutorial : MonoBehaviour
{
    [SerializeField] private GameObject animFog;

    private void Start()
    {
        TryBeginTutorial(TutorialCtrl.Instance.Lv2Start) ||
        TryBeginTutorial(TutorialCtrl.Instance.LobbyDecor);
    }

    private static bool TryBeginTutorial(ITutorial tutorial)
    {
        if (!tutorial.IsActive()) return false;
        tutorial.Begin();
        return true;
    }

    private void OnEnable()
    {
        TutorialLv2StartActions.ShowLobbyFog += ShowLobbyFog;
    }

    private void OnDisable()
    {
        TutorialLv2StartActions.ShowLobbyFog -= ShowLobbyFog;
    }

    // ----------------------------------------------------------
    //  Tutorial handlers
    // ----------------------------------------------------------

    private void ShowLobbyFog()
    {
        animFog.SetActive(true);
    }
}

using _Game;
using DG.Tweening;
using UnityEngine;

/// <summary>
/// Orchestrator của Tutorial Lv2 Start Sequence.
/// Fire actions theo thứ tự → các subscriber (WorldMap, NPC…) tự xử lý visual.
/// WorldMap.Start() gọi Begin() nếu IsActive().
/// </summary>
public class TutorialLv2Start : MonoBehaviour, ITutorial
{
    // ----------------------------------------------------------
    //  State check
    // ----------------------------------------------------------

    public bool IsActive() =>
        DataSave.TutorialData.isLv1EndSequenceComplete &&
        !DataSave.TutorialData.isLv2StartTutComplete;

    // ----------------------------------------------------------
    //  Entry point — WorldMap gọi khi vào Lobby lần đầu
    // ----------------------------------------------------------

    public void Begin()
    {
        if (!IsActive()) return;

        ShowLobbyFog();
        DOVirtual.DelayedCall(4.5f, () => ShowNPC());
    }

    // ----------------------------------------------------------
    //  Phase 1 — Bật anim fog (anim tự xử lý tàu đến + mây bay ra)
    // ----------------------------------------------------------

    public void ShowLobbyFog()
    {
        TutorialLv2StartActions.ShowLobbyFog?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 3 — NPC xuất hiện nói chuyện
    // ----------------------------------------------------------

    public void ShowNPC()
    {
        TutorialLv2StartActions.ShowNPC?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 4 — NPC biến mất → chuyển sang phase tiếp theo
    // ----------------------------------------------------------

    public void HideNPC()
    {
        TutorialLv2StartActions.HideNPC?.Invoke();
        AnimateLevelIcon();
    }

    // ----------------------------------------------------------
    //  Phase 5 — Icon player nhảy lên level 2
    // ----------------------------------------------------------

    public void AnimateLevelIcon()
    {
        TutorialLv2StartActions.AnimateLevelIcon?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 6 — Button level xuất hiện + bàn tay chỉ
    // ----------------------------------------------------------

    public void ShowLevelButton()
    {
        TutorialLv2StartActions.ShowLevelButton?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 7 — Popup xuất hiện + bàn tay chỉ nút play
    // ----------------------------------------------------------

    public void ShowLevelPopup()
    {
        TutorialLv2StartActions.ShowLevelPopup?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 8 — Hoàn thành tutorial (player play hoặc tắt popup)
    // ----------------------------------------------------------

    public void CompleteTutorial()
    {
        if (!IsActive()) return;

        DataSave.TutorialData.SetLv2StartTutComplete();
        TutorialLv2StartActions.CompleteTutorial?.Invoke();
    }
}

using _Game;
using DG.Tweening;
using UnityEngine;

/// <summary>
/// Orchestrator của Tutorial Lobby Decor.
/// Fire actions theo thứ tự → các subscriber (UI Decor, NPC, HUD…) tự xử lý visual.
/// WorldMap.Start() gọi Begin() nếu IsActive().
/// </summary>
public class TutorialLobbyDecor : MonoBehaviour, ITutorial
{
    // ----------------------------------------------------------
    //  State check
    // ----------------------------------------------------------

    public bool IsActive() =>
        DataSave.ResourceData.stars > 5 &&
        !DataSave.TutorialData.isLobbyDecorTutComplete;

    // ----------------------------------------------------------
    //  Entry point — WorldMap gọi khi vào Lobby
    // ----------------------------------------------------------

    public void Begin()
    {
        if (!IsActive()) return;

        ShowNPC();
    }

    // ----------------------------------------------------------
    //  Phase 1 — NPC xuất hiện nói chuyện giới thiệu Decor
    // ----------------------------------------------------------

    public void ShowNPC()
    {
        TutorialLobbyDecorActions.ShowNPC?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 2 — Player ấn confirm → NPC biến mất
    // ----------------------------------------------------------

    public void HideNPC()
    {
        TutorialLobbyDecorActions.HideNPC?.Invoke();
        DOVirtual.DelayedCall(0.5f, ShowDecorButton);
    }

    // ----------------------------------------------------------
    //  Phase 3 — Button Decor hiện ra trên HUD
    // ----------------------------------------------------------

    public void ShowDecorButton()
    {
        TutorialLobbyDecorActions.ShowDecorButton?.Invoke();
        DOVirtual.DelayedCall(0.5f, ShowDecorButtonHand);
    }

    // ----------------------------------------------------------
    //  Phase 4 — Fade-in panel đen + bàn tay chỉ vào nút Decor
    // ----------------------------------------------------------

    public void ShowDecorButtonHand()
    {
        TutorialLobbyDecorActions.ShowDecorButtonHand?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 5 — Player ấn nút Decor → UI Decor mở, bàn tay chỉ Landmark đầu tiên
    // ----------------------------------------------------------

    public void ShowDecorUI()
    {
        TutorialLobbyDecorActions.ShowDecorUI?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 6 — Player bấm Landmark → anim hiển thị diễn hoạt
    // ----------------------------------------------------------

    public void PlayLandmarkAnim()
    {
        TutorialLobbyDecorActions.PlayLandmarkAnim?.Invoke();
    }

    // ----------------------------------------------------------
    //  Phase 7 — Anim kết thúc → back về Lobby, hoàn thành tutorial
    // ----------------------------------------------------------

    public void CompleteTutorial()
    {
        if (!IsActive()) return;

        DataSave.TutorialData.SetLobbyDecorTutComplete();
        TutorialLobbyDecorActions.CompleteTutorial?.Invoke();
    }
}

