using System;
using DG.Tweening;
using UnityEngine;

public class TutorialHand : MonoBehaviour
{
    [SerializeField] private Animator anim;
    public void Start()
    {
        Hide();
    }

    public void Hide()
    {
        this.gameObject.SetActive(false);
        this.transform.DOKill();
    }

    public void Show(Transform tran)
    {
        this.gameObject.SetActive(true);
        this.gameObject.transform.position = tran.position;
    }

    public void Move(Vector3 posEnd, Action onComplete)
    {
        this.anim.Play($"HandDrag");
        this.transform.DOMove(posEnd, 1f).SetDelay(0.25f).OnComplete(() =>
        {
            onComplete?.Invoke();

        });
    }
}

